'use client';

import React, { useEffect, useState, useRef } from 'react';
import JSZip from 'jszip';
import { pdf } from 'book-pdf';
import { Book } from '@/types/book';
import { BookMetadata } from '@/libs/document';
import { formatPublisher, getLocalBookFilename } from '@/utils/book';
import { useEnv } from '@/context/EnvContext';
import type { PaperbackCoverOptions } from '@/lib/paperback-cover';
import type { PaperbackCoverResult } from '@/lib/paperback-cover-browser';
import {
  getSpineItems,
  extractChapters,
  extractCopyrightHtml,
  resolveTitlePageText,
  BookDocument,
  resetElementKeyCounter,
  type PdfOptions,
} from '@/lib/epub-to-pdf';

interface PdfModalProps {
  book: Book;
  bookMeta: BookMetadata | null;
  isOpen: boolean;
  onClose: () => void;
  includeToc: boolean;
  includeChapterHeadings: boolean;
  paperbackCover?: PaperbackCoverOptions;
}

type Phase = 'loading' | 'done' | 'error';

interface Progress {
  message: string;
  percent: number;
}

const PdfModal: React.FC<PdfModalProps> = ({
  book,
  bookMeta,
  isOpen,
  onClose,
  includeToc,
  includeChapterHeadings,
  paperbackCover,
}) => {
  const { envConfig } = useEnv();
  const [phase, setPhase] = useState<Phase>('loading');
  const [progress, setProgress] = useState<Progress>({ message: 'Preparing...', percent: 0 });
  const [error, setError] = useState<string>('');
  const cancelledRef = useRef(false);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const downloadUrls = useRef<string[]>([]);
  const [downloads, setDownloads] = useState<{
    interior: string; cover?: string; warnings: string[]; coverError?: string;
    dimensions?: PaperbackCoverResult['dimensions'];
  } | null>(null);

  useEffect(() => () => { downloadUrls.current.forEach(url => URL.revokeObjectURL(url)); }, []);

  useEffect(() => {
    if (!isOpen) {
      downloadUrls.current.forEach(url => URL.revokeObjectURL(url));
      downloadUrls.current = [];
      setDownloads(null);
      setPhase('loading');
      setProgress({ message: 'Preparing...', percent: 0 });
      setError('');
      cancelledRef.current = false;
      return;
    }

    cancelledRef.current = false;
    let stopped = false;
    const isCancelled = () => stopped || cancelledRef.current;

    const run = async () => {
      try {
        setPhase('loading');
        setProgress({ message: 'Loading epub...', percent: 2 });

        const appService = await envConfig.getAppService();
        const epubFilename = getLocalBookFilename(book);
        const epubFile = await appService.openFile(epubFilename, 'Books');
        const arrayBuffer = await epubFile.arrayBuffer();

        if (isCancelled()) return;

        setProgress({ message: 'Parsing epub...', percent: 10 });
        const zip = await JSZip.loadAsync(arrayBuffer);

        if (isCancelled()) return;

        setProgress({ message: 'Reading spine order...', percent: 20 });
        const spinePaths = await getSpineItems(zip);

        if (isCancelled()) return;

        setProgress({ message: 'Extracting chapters...', percent: 30 });
        const chapters = await extractChapters(zip, spinePaths);

        if (chapters.length === 0) {
          throw new Error('No chapter content found in epub');
        }

        if (isCancelled()) return;

        setProgress({ message: 'Extracting copyright...', percent: 40 });
        const copyrightHtml = await extractCopyrightHtml(zip, spinePaths);

        if (isCancelled()) return;

        setProgress({ message: 'Reading title page...', percent: 45 });
        const titlePage = await resolveTitlePageText(zip, spinePaths, {
          title: book.title || 'Untitled',
          subtitle: bookMeta?.subtitle,
          publisher: bookMeta?.publisher ? formatPublisher(bookMeta.publisher) : undefined,
        });

        if (isCancelled()) return;

        setProgress({ message: 'Laying out pages...', percent: 50 });

        resetElementKeyCounter();
        const options: PdfOptions = {
          title: titlePage.title,
          subtitle: titlePage.subtitle,
          author: book.author || 'Unknown',
          publisher: titlePage.publisher,
          copyrightHtml: copyrightHtml ?? undefined,
          includeToc,
          includeChapterHeadings,
        };

        let finishedPageCount = 0;
        const blob = await pdf(<BookDocument chapters={chapters} options={options} onRender={({ _INTERNAL__LAYOUT__DATA_ }) => {
          finishedPageCount = _INTERNAL__LAYOUT__DATA_.children.length;
        }} />).toBlob();

        if (isCancelled()) return;

        if (paperbackCover) {
          setProgress({ message: 'Creating your paperback cover...', percent: 90 });
          // Give the progress message a chance to paint before preparing the cover.
          await new Promise<void>(resolve => setTimeout(resolve, 0));
          if (isCancelled()) return;
          const interiorUrl = URL.createObjectURL(blob);
          downloadUrls.current.push(interiorUrl);
          try {
            const { generatePaperbackCover } = await import('@/lib/paperback-cover-browser');
            if (isCancelled()) return;
            const result = await generatePaperbackCover(zip, finishedPageCount, paperbackCover, titlePage.title, book.author || 'Unknown', isCancelled);
            if (isCancelled()) return;
            const coverUrl = URL.createObjectURL(result.blob);
            downloadUrls.current.push(coverUrl);
            setDownloads({ interior: interiorUrl, cover: coverUrl, warnings: result.warnings, dimensions: result.dimensions });
          } catch (coverFailure) {
            if (isCancelled()) return;
            setDownloads({ interior: interiorUrl, warnings: [], coverError: coverFailure instanceof Error ? coverFailure.message : 'The cover could not be created.' });
          }
          setPhase('done');
          return;
        }

        setProgress({ message: 'Opening PDF...', percent: 95 });
        const url = URL.createObjectURL(blob);
        window.open(url, '_blank');

        setPhase('done');

        // Auto-close after a brief delay
        setTimeout(() => {
          if (!isCancelled()) {
            onCloseRef.current();
          }
        }, 800);
      } catch (err) {
        if (isCancelled()) return;
        console.error('PDF generation failed:', err);
        setError(err instanceof Error ? err.message : 'PDF generation failed');
        setPhase('error');
      }
    };

    run();

    return () => {
      stopped = true;
      cancelledRef.current = true;
    };
  }, [isOpen, book, bookMeta, envConfig, includeToc, includeChapterHeadings, paperbackCover]);

  // Escape key
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onCloseRef.current();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen]);

  if (!isOpen) return null;

  if (phase === 'done' && downloads) {
    const filename = (book.title || 'Book').replace(/[<>:"/\\|?*]/g, '').slice(0, 120).trim() || 'Book';
    return (
      <div className='fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4'>
        <div role='dialog' aria-modal='true' aria-label='Your paperback PDFs' className='bg-base-100 w-full max-w-lg max-h-[90vh] overflow-y-auto rounded-lg p-6 shadow-xl'>
          <h3 className='text-lg font-semibold mb-3'>{downloads.cover ? 'Your paperback PDFs are ready' : 'Your interior PDF is ready'}</h3>
          {downloads.dimensions && <p className='text-sm mb-4'>6 × 9 inches · {downloads.dimensions.pdfPages} interior pages</p>}
          {downloads.coverError && <p role='alert' className='text-sm text-error mb-4'>The cover could not be created: {downloads.coverError}</p>}
          {downloads.warnings.length > 0 && <ul className='list-disc pl-5 text-sm space-y-2 mb-4'>{downloads.warnings.map(message => <li key={message}>{message}</li>)}</ul>}
          <div className='flex flex-wrap gap-3 mb-4'>
            <a className='btn btn-primary btn-sm' href={downloads.interior} download={`${filename}-6x9-interior.pdf`}>Download interior PDF</a>
            {downloads.cover && <a className='btn btn-primary btn-sm' href={downloads.cover} download={`${filename}-6x9-cover.pdf`}>Download cover PDF</a>}
          </div>
          {downloads.cover && <a className='link text-sm' href={downloads.cover} target='_blank' rel='noreferrer'>View cover PDF</a>}
          <p className='text-sm text-base-content/70 mt-4'>Use these files together. If you change the book or its PDF options, create a new matching pair.</p>
          <div className='flex justify-end mt-4'><button className='btn btn-ghost btn-sm' onClick={onClose}>Close</button></div>
        </div>
      </div>
    );
  }

  // Error state
  if (phase === 'error') {
    return (
      <div className='fixed inset-0 z-[60] flex items-center justify-center bg-base-100'>
        <div className='text-center max-w-sm px-4'>
          <div className='text-4xl mb-4'>
            <svg className='mx-auto' width='48' height='48' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='1.5' strokeLinecap='round' strokeLinejoin='round'>
              <circle cx='12' cy='12' r='10' className='stroke-error' />
              <line x1='15' y1='9' x2='9' y2='15' className='stroke-error' />
              <line x1='9' y1='9' x2='15' y2='15' className='stroke-error' />
            </svg>
          </div>
          <p className='text-error font-semibold mb-2'>PDF Generation Failed</p>
          <p className='text-base-content/60 text-sm mb-4'>{error}</p>
          <button className='btn btn-ghost btn-sm' onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    );
  }

  // Loading / done state
  return (
    <div className='fixed inset-0 z-[60] flex items-center justify-center bg-base-100'>
      <div className='text-center max-w-sm px-4'>
        {/* PDF icon */}
        <div className='mb-4'>
          <svg className='mx-auto text-red-500' width='48' height='48' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='1.5' strokeLinecap='round' strokeLinejoin='round'>
            <path d='M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z' />
            <polyline points='14 2 14 8 20 8' />
            <line x1='16' y1='13' x2='8' y2='13' />
            <line x1='16' y1='17' x2='8' y2='17' />
            <polyline points='10 9 9 9 8 9' />
          </svg>
        </div>

        <h3 className='text-base-content font-semibold text-lg mb-2'>Building PDF</h3>
        <p className='text-base-content/60 text-sm mb-4'>{progress.message}</p>

        {/* Progress bar */}
        <div className='w-full h-1.5 bg-base-300 rounded-full overflow-hidden mb-2'>
          <div
            className='h-full bg-gradient-to-r from-red-600 to-red-400 rounded-full'
            style={{ width: `${progress.percent}%`, transition: 'width 0.3s' }}
          />
        </div>
        <p className='text-base-content/40 text-xs font-mono mb-6'>{progress.percent}%</p>

        <button
          className='btn btn-ghost btn-sm'
          onClick={() => {
            cancelledRef.current = true;
            onClose();
          }}
        >
          Cancel
        </button>
      </div>
    </div>
  );
};

