'use client';

import React, { useEffect, useState } from 'react';
import { BACK_COVER_LIMIT, PAPER_CHOICES, characterCount, limitBackText, type PaperChoice, type PaperbackCoverOptions } from '@/lib/paperback-cover';

export interface PdfContentOptions {
  includeToc: boolean;
  includeChapterHeadings: boolean;
  paperbackCover?: PaperbackCoverOptions;
}

interface PdfOptionsDialogProps {
  isOpen: boolean;
  formatLabel: string;   // e.g. "6x9 inch PDF (KDP)"
  supportsCover?: boolean;
  onCancel: () => void;
  onCreate: (options: PdfContentOptions) => void;
}

const PdfOptionsDialog: React.FC<PdfOptionsDialogProps> = ({
  isOpen,
  formatLabel,
  supportsCover = false,
  onCancel,
  onCreate,
}) => {
  const [includeToc, setIncludeToc] = useState(false);
  const [includeChapterHeadings, setIncludeChapterHeadings] = useState(false);
  const [includeCover, setIncludeCover] = useState(false);
  const [paper, setPaper] = useState<PaperChoice>('bw-white');
  const [backText, setBackText] = useState('');
  const [coverError, setCoverError] = useState<string | null>(null);
  const [checkingText, setCheckingText] = useState(false);

  // Both options start unchecked every time the dialog opens
  useEffect(() => {
    if (isOpen) {
      setIncludeToc(false);
      setIncludeChapterHeadings(false);
      setIncludeCover(false);
      setCoverError(null);
    }
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen || !supportsCover || !includeCover) return;
    let active = true;
    setCheckingText(true);
    import('book-pdf/cover').then(({ checkBackCoverText }) => {
      if (active) setCoverError(checkBackCoverText(backText));
    }).catch(() => {
      if (active) setCoverError('The cover lettering could not be prepared. Please close this dialog and try again.');
    }).finally(() => { if (active) setCheckingText(false); });
    return () => { active = false; };
  }, [isOpen, supportsCover, includeCover, backText]);

  // Escape key
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onCancel();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onCancel]);

  if (!isOpen) return null;

  return (
    <div className='fixed inset-0 z-[60] flex items-center justify-center bg-black/50'>
      <div role='dialog' aria-modal='true' aria-label='PDF Options' className='bg-base-100 w-full max-w-md max-h-[90vh] overflow-y-auto rounded-lg p-6 shadow-xl'>
        <h3 className='text-base-content text-lg font-semibold'>PDF Options</h3>
        <p className='text-base-content/60 mb-5 text-sm'>{formatLabel}</p>

        <label className='mb-3 flex cursor-pointer items-center gap-3'>
          <input
            type='checkbox'
            className='checkbox checkbox-sm'
            checked={includeToc}
            onChange={(e) => setIncludeToc(e.target.checked)}
          />
          <span className='text-base-content text-sm'>Include Table of Contents</span>
        </label>

        <label className='mb-6 flex cursor-pointer items-center gap-3'>
          <input
            type='checkbox'
            className='checkbox checkbox-sm'
            checked={includeChapterHeadings}
            onChange={(e) => setIncludeChapterHeadings(e.target.checked)}
          />
          <span className='text-base-content text-sm'>Include Chapter Headings</span>
        </label>

        {supportsCover && (
          <div className='mb-6 border-t border-base-300 pt-4'>
            <label className='flex cursor-pointer items-center gap-3'>
              <input type='checkbox' className='checkbox checkbox-sm' checked={includeCover} onChange={(event) => setIncludeCover(event.target.checked)} />
              <span className='text-base-content text-sm'>Also create paperback cover</span>
            </label>
            {includeCover && (
              <div className='mt-4 space-y-4'>
                <p className='text-sm text-base-content/70'>Uses this EPUB’s cover. The front, back, and spine are arranged automatically.</p>
                <label className='block text-sm'>
                  Interior printing and paper
                  <select className='select select-bordered select-sm mt-1 w-full' value={paper} onChange={(event) => setPaper(event.target.value as PaperChoice)}>
                    {Object.entries(PAPER_CHOICES).map(([value, choice]) => <option key={value} value={value}>{choice.label}</option>)}
                  </select>
                </label>
                <label className='block text-sm'>
                  Back-cover text
                  <textarea className='textarea textarea-bordered mt-1 w-full h-32 text-base' value={backText}
                    onChange={(event) => setBackText(limitBackText(event.target.value))} aria-describedby='back-cover-count back-cover-error' />
                </label>
                <p id='back-cover-count' className='text-xs text-base-content/70'>{characterCount(backText).toLocaleString()} / {BACK_COVER_LIMIT.toLocaleString()} characters, including spaces. Printed in 14-point EB Garamond.</p>
                {coverError && <p id='back-cover-error' role='alert' className='text-sm text-error'>{coverError}</p>}
                <p className='text-xs text-base-content/70'>Choose the same printing and paper when publishing on KDP. A space for KDP’s barcode is included.</p>
              </div>
            )}
          </div>
        )}

        <div className='flex justify-end gap-2'>
          <button className='btn btn-ghost btn-sm' onClick={onCancel}>
            Cancel
          </button>
          <button
            className='btn btn-primary btn-sm'
            disabled={supportsCover && includeCover && (checkingText || !!coverError)}
            onClick={() => onCreate({ includeToc, includeChapterHeadings, ...(supportsCover && includeCover ? { paperbackCover: { paper, backText } } : {}) })}
          >
            Create PDF
          </button>
        </div>
      </div>
    </div>
  );
};

export default PdfOptionsDialog;

import React from 'react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import PdfOptionsDialog from './PdfOptionsDialog';

afterEach(cleanup);
describe('paperback option in the existing PDF dialog', () => {
  it('keeps the existing 5x8 options and excludes covers', () => {
    const create = vi.fn();
    render(<PdfOptionsDialog isOpen formatLabel='5x8 inch PDF (KDP)' onCancel={vi.fn()} onCreate={create} />);
    expect(screen.queryByLabelText('Also create paperback cover')).toBeNull();
    fireEvent.click(screen.getByText('Create PDF'));
    expect(create).toHaveBeenCalledWith({ includeToc: false, includeChapterHeadings: false });
  });
  it('passes the selected paper and text only when the 6x9 cover is enabled', async () => {
    const create = vi.fn();
    render(<PdfOptionsDialog isOpen supportsCover formatLabel='6x9 inch PDF (KDP)' onCancel={vi.fn()} onCreate={create} />);
    fireEvent.click(screen.getByLabelText('Also create paperback cover'));
    fireEvent.change(screen.getByLabelText('Interior printing and paper'), { target: { value: 'premium-color' } });
    fireEvent.change(screen.getByLabelText('Back-cover text'), { target: { value: 'A quiet valley. An unexpected visitor.' } });
    fireEvent.click(screen.getByLabelText('Include Table of Contents'));
    await waitFor(() => expect((screen.getByText('Create PDF') as HTMLButtonElement).disabled).toBe(false), { timeout: 4000 });
    fireEvent.click(screen.getByText('Create PDF'));
    expect(create).toHaveBeenCalledWith({ includeToc: true, includeChapterHeadings: false,
      paperbackCover: { paper: 'premium-color', backText: 'A quiet valley. An unexpected visitor.' } });
  });
  it('limits pasted text and prevents creating a cover with overflowing paragraphs', async () => {
    render(<PdfOptionsDialog isOpen supportsCover formatLabel='6x9 inch PDF (KDP)' onCancel={vi.fn()} onCreate={vi.fn()} />);
    fireEvent.click(screen.getByLabelText('Also create paperback cover'));
    fireEvent.change(screen.getByLabelText('Back-cover text'), { target: { value: 'a'.repeat(1600) } });
    expect((screen.getByLabelText('Back-cover text') as HTMLTextAreaElement).value.length).toBe(1500);
    fireEvent.change(screen.getByLabelText('Back-cover text'), { target: { value: 'A\n'.repeat(100) } });
    await screen.findByRole('alert');
    expect((screen.getByText('Create PDF') as HTMLButtonElement).disabled).toBe(true);
  });
});

